91		if l.findPlan("P-NEW") != nil || l.findPlan("P-OTHER") != nil || l.findPlan("P-2") != nil {
92			t.Fatalf("失败的计划留在了台账中：%+v", l.data.Plans)
93		}
94		if len(l.data.Plans) != 1 {
95			t.Fatalf("失败新建改动了计划数量：%+v", l.data.Plans)
96		}
97		items, err := l.Todos("")
98		if err != nil {
99			t.Fatalf("todos: %v", err)
100		}
101		if len(items) != 0 {
102			t.Fatalf("待办只能看到此前已保存的未结束计划：%+v", items)
103		}
104		if only, err := l.Todos("M-1"); err != nil || len(only) != 0 {
105			t.Fatalf("M-1 待办应为空（P-OLD 已完成）：%+v err=%v", only, err)
106		}
107		views, err := l.Plans("M-1")
108		if err != nil || len(views) != 1 || views[0].Number != "P-OLD" ||
109			views[0].Status != PlanStatusDone || views[0].CertificateNumber != "C-1" {
110			t.Fatalf("M-1 计划查询应只含此前已完成的 P-OLD：%+v err=%v", views, err)
111		}
112		if views2, err := l.Plans("M-2"); err != nil || len(views2) != 0 {
113			t.Fatalf("M-2 不应出现失败计划：%+v err=%v", views2, err)
114		}
115		r, err := l.Review("M-1")
116		if err != nil {
117			t.Fatalf("review: %v", err)
118		}
119		if len(r.Plans) != 1 || r.Plans[0].Number != "P-OLD" || r.Plans[0].Open() {
120			t.Fatalf("核对中只能看到此前保存的 P-OLD（已完成）：%+v", r.Plans)
121		}
122		// 器具状态、证书不受失败申请影响。
123		if inst := l.findInstrument("M-1"); inst.Status != StatusPending {
124			t.Fatalf("失败新建改动了器具状态：%+v", inst)
125		}
126		if cert := l.findCertificate("C-1"); cert == nil {
127			t.Fatal("失败新建后已有证书丢失")
128		}
129	
130		// 恢复文件可写后不必重开台账：先做一次无关的正常状态切换并保存成功，
131		// 失败的新计划不能被顺带写入文件。
132		restoreSaving(t, l)
133		if err := l.SetStatus("M-1", StatusRetired); err != nil {
134			t.Fatalf("恢复后正常操作应能保存: %v", err)
135		}
136		raw, err := os.ReadFile(path)
137		if err != nil {
138			t.Fatalf("读取台账文件: %v", err)
139		}
140		for _, banned := range []string{"P-NEW", "P-OTHER", "P-2", "年度例行校准", "失败那次的说明"} {
141			if strings.Contains(string(raw), banned) {
142				t.Fatalf("失败的新计划被随后成功的写盘顺带写入文件（含 %q）：\n%s", banned, raw)
143			}
144		}
145		reopened, err := openAt(path, clock.now)
146		if err != nil {
147			t.Fatalf("reopen: %v", err)
148		}
149		if rp := reopened.findPlan("P-NEW"); rp != nil {
150			t.Fatalf("文件中不应出现失败计划：%+v", rp)
151		}
152		if rp := reopened.findPlan("P-OLD"); rp == nil || rp.Status != PlanStatusDone ||
153			rp.CertificateNumber != "C-1" {
154			t.Fatalf("此前已完成的计划信息应保持原样：%+v", rp)
155		}
156	
157		// 在同一台账对象重新提交相同编号和内容才真正建立；此时仍是 10-05，
158		// 计划日期 10-10 仍在未来。建立时间必须取本次成功申请的时间，
159		// 而不是失败那次的 10-03。
160		clock.t = mustDate(t, "2026-10-05")
161		ok, err := l.CreatePlan(in)
162		if err != nil || ok == nil {
163			t.Fatalf("恢复后重新提交应成功建立：err=%v plan=%v", err, ok)
164		}
165		if ok.Number != "P-NEW" || ok.Status != PlanStatusOpen ||
166			ok.PlannedDate != "2026-10-10" || ok.OriginalDate != "2026-10-10" ||
167			ok.Note != "年度例行校准" {
168			t.Fatalf("成功建立的计划内容异常：%+v", ok)
169		}
170		if ok.CreatedAt != "2026-10-05T00:00:00Z" {
171			t.Fatalf("建立时间应取本次成功申请的时间，得到 %s", ok.CreatedAt)
172		}
173		// 新计划出现在该器具的待办与核对中；P-OLD 仍为已完成、关联证书不变。
174		items, err = l.Todos("M-1")
175		if err != nil || len(items) != 1 || items[0].PlanNumber != "P-NEW" ||
176			items[0].Marker != TodoFuture {
177			t.Fatalf("成功建立后待办应只列 P-NEW：%+v err=%v", items, err)
178		}
179		r, err = l.Review("M-1")
180		if err != nil || len(r.Plans) != 2 {
181			t.Fatalf("核对应含 P-OLD 与新建立的 P-NEW：%+v err=%v", r, err)
182		}
183		var donePlan *PlanView
184		for i := range r.Plans {
185			if r.Plans[i].Number == "P-OLD" {
186				donePlan = &r.Plans[i]
187			}
188		}
189		if donePlan == nil || donePlan.Status != PlanStatusDone ||
190			donePlan.CertificateNumber != "C-1" || donePlan.CompletedAt != oldDone.CompletedAt {
191			t.Fatalf("此前完成信息应保持原样：%+v", donePlan)
192		}
193	
194		// 恢复后重新提交时，日期必须按本次申请的本机今天判断：时钟走到 10-11，
195		// M-2 仍按原内容（日期 10-10）提交应明确业务拒绝，台账仍不新增计划。
196		clock.t = mustDate(t, "2026-10-11")
197		if _, err := l.CreatePlan(m2); !IsValidation(err) ||
198			!strings.Contains(err.Error(), "不能早于本机今天") {
199			t.Fatalf("原计划日期已过时应业务拒绝：%v", err)
200		}
201		if l.findPlan("P-2") != nil || len(l.data.Plans) != 2 {
202			t.Fatalf("过去日期的重新提交不得新增计划：%+v", l.data.Plans)
203		}
204		// 换成不早于今天的日期重新提交才建立，建立时间取本次成功申请。
205		ok2, err := l.CreatePlan(PlanInput{Number: "P-2", InstrumentID: "M-2",
206			Date: "2026-10-20", Note: "重新提交的说明"})
207		if err != nil || ok2 == nil {
208			t.Fatalf("未来日期重新提交应成功：err=%v plan=%v", err, ok2)
209		}
210		if ok2.CreatedAt != "2026-10-11T00:00:00Z" || ok2.PlannedDate != "2026-10-20" {
211			t.Fatalf("新计划应采用本次申请的时间与日期：%+v", ok2)
212		}
213	
214		// 重开文件：磁盘上只有 P-OLD、P-NEW、P-2 三项，且不含失败申请的说明。
215		reopened, err = openAt(path, clock.now)
216		if err != nil {
217			t.Fatalf("reopen: %v", err)
218		}
219		if len(reopened.data.Plans) != 3 {
220			t.Fatalf("重开后应只有三项计划：%+v", reopened.data.Plans)
221		}
222		if reopened.findPlan("P-NEW") == nil || reopened.findPlan("P-2") == nil {
223			t.Fatal("重开后找不到成功建立的计划")
224		}
225		raw, err = os.ReadFile(path)
226		if err != nil {
227			t.Fatalf("读取台账文件: %v", err)
228		}
229		if strings.Contains(string(raw), "失败那次的说明") ||
230			strings.Contains(string(raw), "P-OTHER") {
231			t.Fatalf("失败申请的内容最终仍被写入文件：\n%s", raw)
232		}
233	}
234	
235	// TestCreatePlanValidationRejectedWhileSavingBlocked 区分文件读写错误与业务
236	// 拒绝：文件不可写时，编号重复、器具已有未结束计划、日期或说明不符合要求、
237	// 未知器具等仍按原有方式拒绝（校验错误或 ErrNotFound），不触碰写盘、不留计划。
238	func TestCreatePlanValidationRejectedWhileSavingBlocked(t *testing.T) {
239		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
240		path := filepath.Join(t.TempDir(), "ledger.json")
241		l, err := openAt(path, clock.now)
242		if err != nil {
243			t.Fatalf("open: %v", err)
244		}
245		mustRegister(t, l, "M-1", "万用表", 0.5)
246		mustRegister(t, l, "M-2", "示波器", 1.0)
247		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1",
248			Date: "2026-10-10", Note: "周期"})
249	
250		blockSaving(t, l)
251		cases := []struct {
252			name     string
253			in       PlanInput
254			notFound bool
255		}{
256			{"编号重复", PlanInput{Number: "P-1", InstrumentID: "M-2", Date: "2026-10-10", Note: "复用"}, false},
257			{"器具已有未结束计划", PlanInput{Number: "P-2", InstrumentID: "M-1", Date: "2026-10-10", Note: "二"}, false},
258			{"空白编号", PlanInput{Number: "  ", InstrumentID: "M-2", Date: "2026-10-10", Note: "x"}, false},
259			{"空白说明", PlanInput{Number: "P-3", InstrumentID: "M-2", Date: "2026-10-10", Note: ""}, false},
260			{"日期早于今天", PlanInput{Number: "P-3", InstrumentID: "M-2", Date: "2026-10-01", Note: "x"}, false},
261			{"不存在的日期", PlanInput{Number: "P-3", InstrumentID: "M-2", Date: "2026-02-30", Note: "x"}, false},
262			{"未知器具", PlanInput{Number: "P-3", InstrumentID: "X-9", Date: "2026-10-10", Note: "x"}, true},
263		}
264		for _, tc := range cases {
265			t.Run(tc.name, func(t *testing.T) {
266				got, err := l.CreatePlan(tc.in)
267				if err == nil {
268					t.Fatalf("用例 %q 应被拒绝", tc.name)
269				}
270				if got != nil {
271					t.Fatalf("业务拒绝不能返回计划结果：%+v", got)
272				}
273				if tc.notFound {
274					if !errors.Is(err, ErrNotFound) {
275						t.Fatalf("用例 %q 应报 ErrNotFound：%v", tc.name, err)
276					}
277				} else if !IsValidation(err) {
278					t.Fatalf("用例 %q 应是业务校验错误而非文件错误：%v", tc.name, err)
279				}
280			})
281		}
282	
283		// 业务拒绝不写盘、不留计划：台账仍只有此前保存的 P-1。
284		if len(l.data.Plans) != 1 || l.findPlan("P-1") == nil {
285			t.Fatalf("业务拒绝后计划被改动：%+v", l.data.Plans)
286		}
287		items, err := l.Todos("")
288		if err != nil || len(items) != 1 || items[0].PlanNumber != "P-1" {
289			t.Fatalf("待办应仍只含此前保存的 P-1：%+v err=%v", items, err)
290		}
291	}
